/bin/bash -lc "node --input-type=module <<'JS'
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import assert from 'node:assert/strict';
const child = spawn('npm', ['start'], { env: { ...process.env, PORT: '0', DB_PATH: ':memory:' }, detached: true, stdio: ['ignore', 'pipe', 'pipe'] });
let output = '';
child.stderr.on('data', chunk => process.stderr.write(chunk));
const timer = setTimeout(() => { process.kill(-child.pid, 'SIGTERM'); process.exitCode = 1; }, 5000);
try {
  const port = await new Promise((resolve, reject) => {
    child.once('error', reject);
    child.once('exit', code => reject(new Error("'`npm start exited: ${code}`)));
    child.stdout.on('"'data', chunk => {
      output += chunk;
      const match = output.match(/listening on port (\\d+)/);
      if (match) resolve(match[1]);
    });
  });
  const response = await fetch("'`http://127.0.0.1:${port}/health`);
  assert.equal(response.status, 200);
  assert.deepEqual(await response.json(), { status: '"'ok' });
  console.log('npm start and /health verified');
} finally {
  clearTimeout(timer);
  const exited = once(child, 'exit');
  process.kill(-child.pid, 'SIGTERM');
  await exited;
}
